/* Giao diện Quân sự — nạp sau CSS gốc trong index.html */
/* ================= Giao diện TACTICAL (quân sự): góc vuông, khối chắc, xanh olive — ghi đè phần trên ================= */
:root{
  --bg:#e7e9df;--panel:#f6f7f1;--line:#c3c8b4;--line2:#9ea58c;--text:#1d2216;--muted:#5b6250;--soft:#dde1d3;
  --accent:#4f6228;--accent-ink:#f4f6ec;--ok:#3d7a35;--warn:#a87b12;--bad:#a2392b;--run:#2d6b75;--mgr:#5d4a86;--me:#dfe6cc;
  --fill:#dfe2d4;--header:#1e2418;--header-ink:#dfe6cc;
  --f-head:"DIN Condensed","Bahnschrift","Arial Narrow","Helvetica Neue",sans-serif;
  --f-mono:ui-monospace,"SF Mono",Menlo,Consolas,monospace;
}
:root[data-dark="1"]{
  --bg:#0d100b;--panel:#151a12;--line:#2b3324;--line2:#46523a;--text:#e2e7d6;--muted:#8d977f;--soft:#1c2218;
  --accent:#8fa65a;--accent-ink:#0d100b;--ok:#79ad61;--warn:#d6a03e;--bad:#cf5d48;--run:#6aaeb9;--mgr:#a995d6;--me:#26301d;
  --fill:#1f261a;--header:#0a0c08;--header-ink:#cdd6b8;
}
*{border-radius:0}
body{font:14px/1.5 -apple-system,BlinkMacSystemFont,"Helvetica Neue",Arial,sans-serif;-webkit-font-smoothing:antialiased;
  background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);
  background-size:48px 48px;background-attachment:fixed;background-color:var(--bg)}
:root[data-dark="1"] body{background-image:linear-gradient(rgba(143,166,90,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(143,166,90,.05) 1px,transparent 1px)}
:root[data-dark="0"] body{background-image:linear-gradient(rgba(79,98,40,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(79,98,40,.06) 1px,transparent 1px)}
/* thanh chỉ huy */
header{background:var(--header);color:var(--header-ink);border-bottom:3px solid var(--accent);padding:10px 24px;gap:14px}
header .sub,header #summary{color:color-mix(in srgb,var(--header-ink) 70%,transparent);font-family:var(--f-mono);font-size:11.5px;letter-spacing:.04em;text-transform:uppercase}
.brand{font-family:var(--f-head);font-size:22px;letter-spacing:.22em;font-weight:700;color:var(--header-ink);padding-top:3px}
.brand img{height:26px;filter:grayscale(.2) contrast(1.1)}
.nav,.seg,.tabs,.chip,.btn,.badge,.card,.tbl{border-radius:0!important}
.md h1,.md h2,.md h3,.md h4{font-family:var(--f-head);letter-spacing:.08em;text-transform:uppercase;font-size:17px!important;line-height:1.2;margin:16px 0 6px;padding:0;color:var(--text)}
.md h1{font-size:19px!important}
.nav{background:transparent;border:1px solid color-mix(in srgb,var(--header-ink) 25%,transparent);padding:0;gap:0}
.nav a{font-family:var(--f-head);font-size:15px;letter-spacing:.14em;text-transform:uppercase;color:color-mix(in srgb,var(--header-ink) 70%,transparent);padding:7px 14px 4px;border-right:1px solid color-mix(in srgb,var(--header-ink) 18%,transparent);border-radius:0}
.nav a:last-child{border-right:0}
.nav a.on{background:var(--accent);color:var(--accent-ink);box-shadow:none}
header .btn.pri{font-family:var(--f-head);font-size:15px;letter-spacing:.14em;padding:7px 14px 4px}
.chip{border:1px solid color-mix(in srgb,var(--header-ink) 25%,transparent);background:transparent;color:var(--header-ink);font-family:var(--f-mono);font-size:11px;text-transform:uppercase;letter-spacing:.05em;border-radius:0;padding:3px 8px}
/* nút: chữ nhật, viết hoa */
.btn{border:1px solid var(--line2);background:var(--panel);color:var(--text);border-radius:0;padding:6px 14px;font-weight:600;font-size:12px;letter-spacing:.08em;text-transform:uppercase}
.btn:hover{border-color:var(--text);background:var(--soft)}
.btn.pri{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}
.btn.pri:hover{filter:brightness(1.1);background:var(--accent)}
.btn.danger{color:var(--bad);border-color:color-mix(in srgb,var(--bad) 55%,var(--line2));background:var(--panel)}
.btn.sm{padding:4px 10px;font-size:11px}
/* phân đoạn (kiểu xem, bộ lọc, tab) */
.seg{background:var(--panel);border:1px solid var(--line2);padding:0;gap:0;border-radius:0}
.seg button{border-radius:0;border-right:1px solid var(--line);font-family:var(--f-head);font-size:14px;letter-spacing:.12em;text-transform:uppercase;padding:6px 12px 3px;color:var(--muted)}
.seg button:last-child{border-right:0}
.seg button.on{background:var(--text);color:var(--bg);box-shadow:none}
/* tiêu đề */
.page{padding:28px 24px 60px}
.page>h2,.pagehead h2,.head h2,.page>.row h2{font-family:var(--f-head)!important;font-size:34px!important;letter-spacing:.06em;text-transform:uppercase;font-weight:700;line-height:1.05;padding-top:4px}
.page h4,.prod-h,.dept-h h3{font-family:var(--f-head);font-size:17px;letter-spacing:.16em;text-transform:uppercase;color:var(--text);font-weight:700;border-bottom:2px solid var(--text);padding-bottom:2px;display:inline-block}
.dept-h{border-bottom:1px solid var(--line2);padding-bottom:6px}
.dept-h h3{border:0}
.crumb{font-family:var(--f-head);letter-spacing:.14em;text-transform:uppercase;font-size:14px;color:var(--accent)}
.sub,.meta{color:var(--muted)}
.meta>span:first-child,.tr .meta,.log .tm{font-family:var(--f-mono);font-size:11.5px}
/* khối: góc vuông, viền chắc, thanh tiêu đề */
.card,.stat,.tbl,.desk,.emp,.tcard,.htmlprev,.imgs a,.modal .box,.kcard{border:1px solid var(--line2)!important;border-radius:0!important;background:var(--panel);box-shadow:none!important}
.card{padding:0;margin-bottom:var(--gap-lg)}
.card>h3{margin:0;padding:8px 16px 5px;background:var(--text);color:var(--bg);font-family:var(--f-head);font-size:16px;letter-spacing:.14em;text-transform:uppercase;font-weight:700}
.card>h3 .sub{color:color-mix(in srgb,var(--bg) 70%,transparent);font-family:var(--f-mono);font-size:11px;letter-spacing:.02em;text-transform:none}
.card>:not(h3){margin-left:16px;margin-right:16px}  /* = lề ngang của thẻ nhân viên/bàn làm việc */
.card>:last-child{margin-bottom:16px}
.card>h3+*{margin-top:12px}
.final-card{border-color:var(--ok)!important;border-width:2px!important}
.final-card>h3{background:var(--ok);color:#fff}
.stats{gap:0;border:1px solid var(--line2);background:var(--panel)}
.stat{border:0!important;border-right:1px solid var(--line2)!important;padding:12px 16px}
.stat:last-child{border-right:0!important}
.stat .sub{font-family:var(--f-head);font-size:14px;letter-spacing:.14em;text-transform:uppercase}
.stat b{font-family:var(--f-mono);font-size:30px;font-weight:700;letter-spacing:-.02em}
.stat:hover{background:var(--soft)}
.tr{border-top:1px solid var(--line);padding:11px 16px}
.tr.hd{background:var(--text);color:var(--bg);font-family:var(--f-head);font-size:14px;letter-spacing:.14em;text-transform:uppercase;padding:8px 16px 5px}
.tr.trow:hover{background:var(--soft)}
.tr .t,.tcard .t,.kcard b{font-weight:700}
.kcol{background:transparent;border:1px solid var(--line2);border-radius:0;padding:10px}
.kcol>h5{font-family:var(--f-head);font-size:15px;letter-spacing:.12em;text-transform:uppercase;border-bottom:2px solid var(--text);padding-bottom:4px;margin-bottom:6px}
.desk,.emp,.tcard{border-top:3px solid var(--line2)!important}
.desk.busy{border-top-color:var(--run)!important}
.desk.mgr.busy{border-top-color:var(--mgr)!important}
.desk .nm,.emp .nm{font-family:var(--f-head);font-size:19px;letter-spacing:.08em;text-transform:uppercase;padding-top:2px}
.desk .tool,.emp .prio{border:1px solid var(--line2);border-radius:0;background:transparent;font-family:var(--f-mono);font-size:10.5px;text-transform:uppercase;letter-spacing:.06em}
.desk .job,.loginbox,.viewer,.note,.mstatus{background:var(--soft);border:0;border-left:3px solid var(--accent);border-radius:0}
.mstatus.wait{border:0;border-left:3px solid var(--warn);background:color-mix(in srgb,var(--warn) 12%,var(--panel))}
/* nhãn trạng thái: khối chữ nhật, viết hoa */
.badge{border-radius:0;font-family:var(--f-mono);font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;padding:2px 7px;background:var(--accent);color:var(--accent-ink)}
.badge.xong{background:var(--ok);color:#fff}.badge.cho{background:var(--warn);color:#111}.badge.loi{background:var(--bad);color:#fff}
.dot{border-radius:0;width:8px;height:8px}
.bar{gap:2px}.bar i{height:6px;border-radius:0;background:var(--fill);border:1px solid var(--line)}
.bar i.d{background:var(--ok);border-color:var(--ok)}.bar i.c{background:var(--accent);border-color:var(--accent)}
.ubar .trk,.mini .trk{border-radius:0;background:var(--fill);height:8px;border:1px solid var(--line)}
.ubar .trk i,.mini .trk i{border-radius:0}
.ubar b,.mini b{font-family:var(--f-mono)}
/* ô nhập */
textarea,input[type=text],input[type=search],input[type=password],.field select,.settings select,.hire input,.hire select,.picker>button{
  border:1px solid var(--line2)!important;background:var(--panel)!important;border-radius:0!important;padding:8px 10px!important;color:var(--text);font-family:inherit}
textarea:focus,input:focus,select:focus{outline:2px solid var(--accent);outline-offset:-1px;box-shadow:none}
.field>span,.hire label,.optgroup>b{font-family:var(--f-head);font-size:14px;letter-spacing:.12em;text-transform:uppercase}
.picker .menu{border:1px solid var(--line2);border-radius:0;box-shadow:0 8px 24px rgba(0,0,0,.25);padding:0}
.picker .opt{border-radius:0;border-bottom:1px solid var(--line)}
/* thanh bước: ô vuông */
.st b{border-radius:0;border-width:2px;font-family:var(--f-mono);background:var(--panel)}
.st.d b{background:var(--ok);border-color:var(--ok)}
.st:before{height:2px;background:var(--line2)}
.st div{font-family:var(--f-head);font-size:13px;letter-spacing:.1em;text-transform:uppercase}
/* hội thoại */
.msg{border-radius:0}
.msg.owner{background:var(--accent);color:var(--accent-ink)}
.msg.manager{background:var(--soft);border-left:3px solid var(--mgr)}
.msg.tool{font-family:var(--f-mono)}
.msg.event{font-family:var(--f-mono);font-size:11.5px;text-transform:uppercase;letter-spacing:.04em}
details{border-top:1px solid var(--line)}
summary b{font-family:var(--f-head);font-size:15px;letter-spacing:.1em;text-transform:uppercase}
.log div{border-bottom:1px dashed var(--line)}
.log .who{font-family:var(--f-mono);font-size:11.5px;text-transform:uppercase}
.toast{border-radius:0;background:var(--text);color:var(--bg);font-family:var(--f-mono);font-size:12px;letter-spacing:.04em;text-transform:uppercase;border-left:4px solid var(--accent)}
.modal{background:rgba(0,0,0,.55)}
.imgs .ph{border-radius:0}
.htmlprev .bar2{background:var(--soft);border-bottom:1px solid var(--line2)}
.htmlprev iframe{border-top:0}
/* menu dọc (màn hình rộng): nối liền thanh chỉ huy thành khối chữ L, vạch olive bên phải, mục đang chọn là khối olive đặc */
:root{
  --nav-bg:var(--header);--nav-edge:3px solid var(--accent);
  --nav-font:700 15px/1.25 var(--f-head);--nav-ls:.14em;--nav-tt:uppercase;--nav-item-pad:10px 16px 7px;--nav-pad:0;
  --nav-ink:color-mix(in srgb,var(--header-ink) 72%,transparent);
  --nav-hover-bg:color-mix(in srgb,var(--header-ink) 9%,transparent);--nav-hover-ink:var(--header-ink);
  --nav-on-bg:var(--accent);--nav-on-ink:var(--accent-ink);--nav-arrow:transparent;
  --nav-line:color-mix(in srgb,var(--header-ink) 18%,transparent);--nav-muted:color-mix(in srgb,var(--header-ink) 55%,transparent)}
@media (min-width:901px){
  :root .nav a{border-bottom:1px solid var(--nav-line)!important}
  :root .nav .ncount{border-radius:0!important;font-family:var(--f-mono)}
}
