.sub,.meta{color:var(--muted)}
.tr .meta,.log .tm{font-family:var(--f-mono);font-size:11.5px}
.md h1,.md h2,.md h3,.md h4{font-family:var(--f-head);letter-spacing:.1em;text-transform:uppercase;font-size:17px!important;margin:16px 0 6px;color:var(--accent)}
/* khối */
.card,.stat,.tbl,.desk,.emp,.tcard,.htmlprev,.imgs a,.modal .box,.kcard{border:1px solid var(--line2)!important;background:var(--panel);box-shadow:var(--glow)!important;backdrop-filter:blur(10px)}
.card{padding:0;margin-bottom:var(--gap-lg)}
.card>h3{margin:0;padding:9px 16px 6px;border-bottom:1px solid var(--line2);background:linear-gradient(90deg,var(--fill),transparent);font-family:var(--f-head);font-size:16px;letter-spacing:.18em;text-transform:uppercase;font-weight:700;color:var(--accent);text-shadow:var(--tglow)}
.card>h3 .sub{font-family:var(--f-mono);font-size:11px;letter-spacing:.02em;text-transform:none;text-shadow:none}
.card>:not(h3){margin-left:16px;margin-right:16px}
.card>:last-child{margin-bottom:16px}
.card>h3+*{margin-top:12px}
.final-card{border-color:var(--ok)!important;box-shadow:0 0 18px color-mix(in srgb,var(--ok) 25%,transparent)!important}
.final-card>h3{color:var(--ok);background:linear-gradient(90deg,color-mix(in srgb,var(--ok) 14%,transparent),transparent);border-bottom-color:color-mix(in srgb,var(--ok) 50%,transparent)}
.stats{gap:0;border:1px solid var(--line2);background:var(--panel)}
.stat{border:0!important;border-right:1px solid var(--line)!important;padding:12px 16px;background:transparent;clip-path:none}
.stat:last-child{border-right:0!important}
.stat .sub{font-family:var(--f-head);font-size:14px;letter-spacing:.16em;text-transform:uppercase}
.stat b{font-family:var(--f-mono);font-size:32px;font-weight:700;color:var(--text);text-shadow:var(--tglow)}
.stat.wait b{color:var(--warn)}.stat.run b{color:var(--run)}.stat.done b{color:var(--ok)}
.stat:hover{background:var(--fill)}
.tr{border-top:1px solid var(--line);padding:11px 16px}
.tr.hd{background:var(--fill);color:var(--accent);font-family:var(--f-head);font-size:14px;letter-spacing:.16em;text-transform:uppercase;padding:8px 16px 5px;border-bottom:1px solid var(--line2)}
.tr.trow:hover{background:var(--fill);box-shadow:inset 3px 0 0 var(--accent)}
.tr .t,.tcard .t,.kcard b{font-weight:700}
.kcol{background:transparent;border:1px solid var(--line);padding:10px}
.kcol>h5{font-family:var(--f-head);font-size:15px;letter-spacing:.14em;text-transform:uppercase;color:var(--accent);border-bottom:1px solid var(--line2);padding-bottom:4px;margin-bottom:6px}
.desk,.emp,.tcard{border-top:2px solid var(--accent)!important}
.desk.busy{box-shadow:0 0 20px color-mix(in srgb,var(--run) 35%,transparent)!important}
.desk.mgr.busy{border-top-color:var(--mgr)!important;box-shadow:0 0 20px color-mix(in srgb,var(--mgr) 35%,transparent)!important}
.desk .nm,.emp .nm{font-family:var(--f-head);font-size:19px;letter-spacing:.1em;text-transform:uppercase;padding-top:2px}
.desk .tool,.emp .prio{border:1px solid var(--line2);background:transparent;font-family:var(--f-mono);font-size:10.5px;text-transform:uppercase;letter-spacing:.06em;color:var(--accent)}
.desk .job,.loginbox,.viewer,.note,.mstatus{background:var(--soft);border:0;border-left:2px solid var(--accent)}
.mstatus.wait{border-left-color:var(--warn);background:color-mix(in srgb,var(--warn) 10%,transparent)}
/* nhãn, chấm, thanh tiến độ */
.badge{font-family:var(--f-mono);font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;padding:2px 8px;background:transparent;color:var(--accent);border:1px solid currentColor;box-shadow:0 0 8px color-mix(in srgb,currentColor 30%,transparent)}
.badge.xong{color:var(--ok);background:transparent}.badge.cho{color:var(--warn);background:transparent}.badge.loi{color:var(--bad);background:transparent}
.dot{border-radius:50%!important;width:8px;height:8px;box-shadow:0 0 8px currentColor}
.dot.ok{color:var(--ok)}.dot.busy{color:var(--warn)}.dot.bad{color:var(--bad)}.dot.run{color:var(--run)}.dot.mgr{color:var(--mgr)}
.bar{gap:3px}.bar i{height:5px;background:var(--fill)}
.bar i.d{background:var(--ok);box-shadow:0 0 6px color-mix(in srgb,var(--ok) 60%,transparent)}
.bar i.c{background:var(--accent);box-shadow:0 0 8px var(--accent)}
.ubar .trk,.mini .trk{background:var(--fill);height:6px}
.ubar .trk i,.mini .trk i{box-shadow:0 0 8px currentColor}
.ubar b,.mini b{font-family:var(--f-mono)}
/* ô nhập */
textarea,input[type=text],input[type=search],input[type=password],.field select,.settings select,.hire input,.hire select,.picker>button{
  border:1px solid var(--line2)!important;background:var(--soft)!important;padding:8px 10px!important;color:var(--text)}
textarea:focus,input:focus,select:focus{outline:none;border-color:var(--accent)!important;box-shadow:0 0 0 1px var(--accent),0 0 14px rgba(56,200,255,.4)}
.field>span,.hire label,.optgroup>b{font-family:var(--f-head);font-size:14px;letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}
.picker .menu{border:1px solid var(--line2);background:var(--bg);box-shadow:0 10px 40px rgba(0,60,140,.35);padding:0}
.picker .opt{border-bottom:1px solid var(--line)}
/* thanh bước */
.st b{border-width:1.5px;font-family:var(--f-mono);background:var(--bg);border-radius:50%!important;border-color:var(--line2)}
.st.d b{background:var(--ok);border-color:var(--ok);color:#021022;box-shadow:0 0 10px var(--ok)}
.st.c b{border-color:var(--accent);color:var(--accent);box-shadow:0 0 12px var(--accent)}
.st:before{height:1px;background:var(--line2)}
.st.d:before{background:var(--ok);box-shadow:0 0 6px var(--ok)}
.st div{font-family:var(--f-head);font-size:13px;letter-spacing:.12em;text-transform:uppercase}
/* hội thoại */
.msg.owner{background:linear-gradient(90deg,var(--accent2),var(--accent));color:#fff}
.msg.manager{background:var(--soft);border-left:2px solid var(--mgr)}
.msg.tool{font-family:var(--f-mono)}
.msg.event{font-family:var(--f-mono);font-size:11.5px;text-transform:uppercase;letter-spacing:.05em}
details{border-top:1px solid var(--line)}
summary b{font-family:var(--f-head);font-size:15px;letter-spacing:.12em;text-transform:uppercase}
.log div{border-bottom:1px solid var(--line)}
.log .who{font-family:var(--f-mono);font-size:11.5px;text-transform:uppercase}
.toast{background:var(--panel);color:var(--text);border:1px solid var(--accent);box-shadow:0 0 20px rgba(56,200,255,.45);font-family:var(--f-mono);font-size:12px;text-transform:uppercase;letter-spacing:.05em;backdrop-filter:blur(12px)}
.modal{background:rgba(2,10,24,.6);backdrop-filter:blur(6px)}
.htmlprev .bar2{background:var(--soft);border-bottom:1px solid var(--line2)}
/* menu dọc (màn hình rộng): tấm kính hologram, chữ cyan phát sáng, mục đang chọn có vạch sáng bên trái */
:root{
  --nav-bg:rgba(255,255,255,.80);--nav-blur:saturate(160%) blur(16px);--nav-edge:1px solid var(--line2);
  --nav-shadow:1px 0 0 rgba(56,200,255,.25),6px 0 30px rgba(0,120,255,.10);
  --nav-font:700 15px/1.25 var(--f-head);--nav-ls:.16em;--nav-tt:uppercase;--nav-item-pad:10px 16px 7px;
  --nav-ink:var(--muted);--nav-hover-bg:var(--fill);--nav-hover-ink:var(--accent);
  --nav-on-bg:linear-gradient(90deg,var(--fill),transparent);--nav-on-ink:var(--accent);
  --nav-on-shadow:inset 3px 0 0 var(--accent),inset 0 0 18px rgba(56,200,255,.12);--nav-on-glow:var(--tglow);
  --nav-arrow:transparent;--nav-line:var(--line2);--nav-muted:var(--muted)}
:root[data-dark="1"]{--nav-bg:rgba(3,12,28,.82)}
@media (min-width:901px){
  :root .nav a.on .ni{filter:drop-shadow(0 0 4px var(--accent))}
  :root .nav .ncount{border-radius:0!important;font-family:var(--f-mono)}
}
<style>
:root{
  --bg:#f6f7f9;--panel:#fff;--line:#e3e6ea;--text:#1d2228;--muted:#69727d;--soft:#f0f2f5;
  --accent:#3b6fd8;--ok:#1f9d55;--warn:#c58a00;--bad:#d64545;--run:#0e8fa6;--mgr:#8a4fd1;--me:#e8f0ff;
  /* kích thước dùng chung cho mọi trang — chỉnh ở đây để các trang luôn đều nhau */
  --page-max:1440px;--gap:14px;--gap-lg:16px;--sect:16px;--radius:12px;--radius-sm:8px;--pad:14px 16px;
  --ctl-h:34px;--ctl-h-sm:28px;--fs-ctl:13px;--title-size:21px;
}
:root[data-dark="1"]{
  --bg:#121417;--panel:#1a1d21;--line:#2b3036;--text:#e6e8eb;--muted:#9099a3;--soft:#22262b;
  --accent:#6f9bff;--ok:#3ccf7f;--warn:#f0b429;--bad:#ff6b6b;--run:#3cc7de;--mgr:#b98aff;--me:#23324f;
}
*{box-sizing:border-box}
[hidden]{display:none!important}
body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif}
a{color:inherit}
button{font:inherit;cursor:pointer}
input[type=text],input[type=search],input[type=password]{font:inherit;font-size:var(--fs-ctl);border:1px solid var(--line);border-radius:var(--radius-sm);padding:6px 10px;background:var(--panel);color:var(--text)}
.btn{border:1px solid var(--line);background:var(--soft);color:var(--text);border-radius:var(--radius-sm);padding:5px 12px;font-size:var(--fs-ctl);text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:6px;white-space:nowrap}
.btn:hover{border-color:var(--muted)}
.btn.pri{background:var(--accent);border-color:var(--accent);color:#fff;font-weight:600}
.btn.danger{color:var(--bad)}.btn.danger:hover{border-color:var(--bad)}
.btn.sm{padding:2px 9px;font-size:12px}
.btn:disabled{opacity:.5;cursor:not-allowed}
header{display:flex;flex-wrap:wrap;gap:12px;align-items:center;padding:10px 20px;border-bottom:1px solid var(--line);background:var(--panel);position:sticky;top:0;z-index:5}
.brand{font-size:17px;margin:0;letter-spacing:2px;display:flex;align-items:center;gap:8px;font-weight:700;text-decoration:none}
.brand img{height:28px;width:auto;filter:drop-shadow(0 1px 1px rgba(0,0,0,.35))}
.nav{display:flex;gap:2px;background:var(--soft);border:1px solid var(--line);border-radius:9px;padding:3px}
.nav a{color:var(--muted);padding:4px 12px;border-radius:7px;font-size:13px;font-weight:600;text-decoration:none;white-space:nowrap}
.nav a.on{background:var(--panel);color:var(--text);box-shadow:0 1px 2px rgba(0,0,0,.12)}
.sub{color:var(--muted);font-size:12.5px}
.chips{display:flex;flex-wrap:wrap;gap:6px;margin-left:auto;text-decoration:none;color:inherit}
a.chips:hover .chip{border-color:var(--muted)}
.chip{display:inline-flex;align-items:center;gap:6px;padding:3px 10px;border:1px solid var(--line);border-radius:99px;font-size:12px;background:var(--soft)}
.dot{width:8px;height:8px;border-radius:50%;background:var(--muted);flex:none;display:inline-block}
.dot.ok{background:var(--ok)}.dot.bad{background:var(--bad)}.dot.run{background:var(--run);animation:pulse 1.2s infinite}.dot.mgr{background:var(--mgr);animation:pulse 1.2s infinite}
@keyframes pulse{50%{opacity:.35}}
.page{padding:22px 26px;max-width:var(--page-max);margin:0 auto}
/* tiêu đề trang: một quy tắc cho mọi trang (trước đây mỗi trang ghi style riêng, trang task lệch margin) */
.page>h2,.pagehead h2,.head h2,.page>.row h2{margin:0 0 2px;font-size:var(--title-size);line-height:1.25}
.page>.sub+h4,#office>h4:first-child,#nvList>.dept:first-child{margin-top:var(--sect)}
.page[data-page="cd"]>.card{max-width:920px}  /* Cài đặt: mọi thẻ cùng độ rộng (trước 620/920/không giới hạn lẫn lộn) */
.page h4{margin:26px 0 10px;font-size:13px;letter-spacing:.6px;text-transform:uppercase;color:var(--muted)}
  :root.navmini{--sw:52px}
  header{position:sticky!important;top:0;z-index:7!important}
  /* backdrop-filter trên header biến header thành khung chứa của .nav (position:fixed) → menu bị kẹt trong header.
     Bỏ nó khỏi header, chuyển hiệu ứng kính mờ sang lớp ::before (không chứa .nav). */
  header{backdrop-filter:none!important;-webkit-backdrop-filter:none!important;filter:none!important;transform:none!important}
  :root[data-theme="apple"] header::before,:root[data-theme="sieu-anh-hung"] header::before{content:"";position:absolute;inset:0;z-index:-1;
    pointer-events:none;backdrop-filter:saturate(170%) blur(18px);-webkit-backdrop-filter:saturate(170%) blur(18px)}
  body>section.page{margin-left:var(--sw)!important;margin-right:0;max-width:calc(var(--page-max) + var(--sw))}
  body>.banner{margin-left:var(--sw)}
  .nav{position:fixed!important;left:0;top:var(--hh);bottom:0;width:var(--sw);max-width:none;z-index:6;margin:0!important;
    display:flex!important;flex-direction:column!important;flex-wrap:nowrap!important;gap:0!important;overflow-x:hidden;overflow-y:auto;
    padding:var(--nav-pad,10px 0)!important;border:0!important;border-right:var(--nav-edge,0)!important;border-radius:0!important;
    background:var(--nav-bg,#1d2327)!important;box-shadow:var(--nav-shadow,none)!important;
    backdrop-filter:var(--nav-blur,none)!important;-webkit-backdrop-filter:var(--nav-blur,none)!important}
  /* Menu dọc: bố cục chung ở đây; màu, chữ, kiểu mục đang chọn lấy từ biến --nav-* do từng giao diện đặt
     (không đặt = kiểu WordPress tối của giao diện Cổ điển). */
  .nav a,.nav a:last-child,.navfold{position:relative;display:flex!important;align-items:center;gap:10px;width:var(--nav-item-w,100%);white-space:nowrap;
    padding:var(--nav-item-pad,9px 14px)!important;margin:var(--nav-item-m,0)!important;border:0!important;border-radius:var(--nav-r,0)!important;
    background:transparent!important;box-shadow:none!important;
    color:var(--nav-ink,#f0f0f1)!important;font:var(--nav-font,500 14px/1.3 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif)!important;
    letter-spacing:var(--nav-ls,0)!important;text-transform:var(--nav-tt,none)!important;text-shadow:none!important;opacity:1!important;text-decoration:none}
  .nav .ni{width:20px;height:20px;opacity:var(--nav-ni-o,.75)}
  .nav a:hover,.navfold:hover{background:var(--nav-hover-bg,#2c3338)!important;color:var(--nav-hover-ink,#72aee6)!important}
  .nav a:hover .ni,.navfold:hover .ni{opacity:1}
  .nav a.on{background:var(--nav-on-bg,var(--accent))!important;color:var(--nav-on-ink,#fff)!important;
    box-shadow:var(--nav-on-shadow,none)!important;text-shadow:var(--nav-on-glow,none)!important}
  .nav a.on .ni{opacity:1}
  .nav a.on:after{content:"";position:absolute;right:0;top:50%;margin-top:-8px;border:8px solid transparent;border-right-color:var(--nav-arrow,var(--bg))}
  .nav .ncount{margin-left:auto;border-radius:9px;font-family:inherit}
  .navfold{margin-top:auto!important;border-top:1px solid var(--nav-line,#2c3338)!important;cursor:pointer;color:var(--nav-muted,#a7aaad)!important;font-size:13px!important}
  .navfold .ni{transition:transform .2s}
  :root.navmini .nav .nl{display:none}
  :root.navmini .nav a,:root.navmini .navfold{justify-content:center;padding:10px 0!important}
  :root.navmini .navfold .ni{transform:rotate(180deg)}
  :root.navmini .nav .ncount{position:absolute;top:3px;right:4px;margin:0;min-width:15px;font-size:10px;line-height:15px;padding:0 3px}
}

