7:.btn.sm{height:var(--ctl-h-sm)}
9:  height:var(--ctl-h);padding-top:0!important;padding-bottom:0!important;font-size:var(--fs-ctl)}
11:.settings select,.turnopts select,.ask input[type=text]{height:var(--ctl-h-sm);padding-top:0!important;padding-bottom:0!important;font-size:var(--fs-ctl)}
13:.seg{min-height:var(--ctl-h)}
16:header .btn,header .btn.sm,header .chip{height:var(--ctl-h);padding-top:0;padding-bottom:0}
17:header .btn.sm.notibtn{width:var(--ctl-h);height:var(--ctl-h);padding:0}
